    def dfs_depth(current_depth, path, visited):
        if len(path) == current_depth:
            return None
        row, col = path[-1]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col) and (new_row, new_col) not in visited:
                new_visited = visited | {(new_row, new_col)}
                new_path = path + [(new_row, new_col)]
                if (new_row, new_col) == (goal_row, goal_col):
                    return new_path
                result = dfs_depth(current_depth, new_path, new_visited)
                if result:
                    return result
        return None

    max_depth = rows * cols
    for depth in range(1, max_depth + 1):
        result = dfs_depth(depth, [start], {(start_row, start_col)})
        if result:
            return result
    return []
