    goal_queue = deque([(goal[0], goal[1], [goal])])

    while start_queue and goal_queue:
        result = bfs(start_queue, start_visited, goal_visited, False)
        if result:
            return result
        result = bfs(goal_queue, goal_visited, start_visited, True)
        if result:
            return result
    return []
