from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols:
        return []
    if goal_row < 0 or goal_row >= rows or goal_col < 0 or goal_col >= cols:
        return []
    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, goal, visited, other_visited):
        queue = deque([(start, [start])])
        visited.add(start)
        while queue:
            current, path = queue.popleft()
            if current in other_visited:
                return path + other_visited[current]
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))
        return []

    # Bidirectional BFS
    visited_from_start = set()
    visited_from_goal = set()
    queue_start = deque([start])
    queue_goal = deque([goal])
    visited_from_start.add(start)
    visited_from_goal.add(goal)
    paths_start = {start: [start]}
    paths_goal = {goal: [goal]}

    while queue_start and queue_goal:
        # Expand from start
        if len(queue_start) <= len(queue_goal):
            current = queue_start.popleft()
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in visited_from_start:
                    visited_from_start.add((nr, nc))
                    queue_start.append((nr, nc))
                    paths_start[(nr, nc)] = paths_start[current] + [(nr, nc)]
                    if (nr, nc) in visited_from_goal:
                        return paths_start[(nr, nc)] + paths_goal[(nr, nc)][::-1][1:]
        else:
            current = queue_goal.popleft()
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in visited_from_goal:
                    visited_from_goal.add((nr, nc))
                    queue_goal.append((nr, nc))
                    paths_goal[(nr, nc)] = paths_goal[current] + [(nr, nc)]
                    if (nr, nc) in visited_from_start:
                        return paths_goal[(nr, nc)] + paths_start[(nr, nc)][::-1][1:]

    return []
