from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0] or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    visited_start = set()
    visited_goal = set()
    start_queue = deque()
    goal_queue = deque()
    start_queue.append((start[0], start[1], [start]))
    goal_queue.append((goal[0], goal[1], [goal]))
    visited_start.add(start)
    visited_goal.add(goal)

    while start_queue and goal_queue:
        # Expand from start
        if start_queue:
            r, c, path = start_queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited_start:
                    visited_start.add((nr, nc))
                    new_path = path + [(nr, nc)]
                    if (nr, nc) in visited_goal:
                        return new_path
                    start_queue.append((nr, nc, new_path))

        # Expand from goal
        if goal_queue:
            r, c, path = goal_queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited_goal:
                    visited_goal.add((nr, nc))
                    new_path = path + [(nr, nc)]
                    if (nr, nc) in visited_start:
                        return new_path[::-1]
                    goal_queue.append((nr, nc, new_path))

    return []
