def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in graph[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check for negative weight cycles that are reachable from s
    in_queue = [False] * n
    queue = deque()
    queue.append(s)
    in_queue[s] = True

    # SPFA (Shortest Path Faster Algorithm)
    while queue:
        u = queue.popleft()
        in_queue[u] = False
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not in_queue[v]:
                    queue.append(v)
                    in_queue[v] = True

    return dist[t] if dist[t] != float('inf') else -1
